#!/usr/bin/env python3
"""Bundle the unchanged dashboard template for the static offline app."""
import json
import hashlib
import base64
import re
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from build_plan_dashboard import TEMPLATE

(ROOT / 'pwa/dashboard-template.mjs').write_text(
    '// Generated by scripts/build_pwa_dashboard.py; edit the source template instead.\n'
    + 'export const dashboardTemplate = ' + json.dumps(TEMPLATE, ensure_ascii=True) + ';\n', encoding='utf-8')

# Embed only locally bundled, verified original PNG bytes. The sandboxed frame
# permits data: images and still has no network access or same-origin privileges.
icon_root = ROOT / 'pwa/assets/egginc'
catalog = json.loads((icon_root / 'manifest.json').read_text(encoding='utf-8'))
for filename, source_path in catalog.get('local_sources', {}).items():
    content = (ROOT / source_path).read_bytes()
    if hashlib.sha256(content).hexdigest() != catalog['files'][filename]:
        raise ValueError('Local artwork differs from recorded checksum: ' + source_path)
    (icon_root / filename).write_bytes(content)
images = {}
for filename, checksum in catalog['files'].items():
    content = (icon_root / filename).read_bytes()
    if hashlib.sha256(content).hexdigest() != checksum:
        raise ValueError('Bundled icon differs from verified upstream bytes: ' + filename)
    images[filename] = 'data:image/png;base64,' + base64.b64encode(content).decode('ascii')
(ROOT / 'pwa/egginc-icons.mjs').write_text(
    '// Generated by scripts/build_pwa_dashboard.py; see assets/egginc/ATTRIBUTION.md.\n'
    + 'export const iconCatalog = ' + json.dumps(catalog, ensure_ascii=True) + ';\n'
    + 'export const iconImages = ' + json.dumps(images, ensure_ascii=True) + ';\n', encoding='utf-8')

# Updating any shell asset changes sw.js, so installed apps fetch a new cache
# without touching the active-plan record. Include this command in asset edits.
assets = sorted(path for path in (ROOT / 'pwa').rglob('*') if path.is_file() and path.name != 'sw.js')
version = hashlib.sha256(b''.join(path.relative_to(ROOT / 'pwa').as_posix().encode() + path.read_bytes()
                                  for path in assets)).hexdigest()[:16]
worker = ROOT / 'pwa/sw.js'
source = worker.read_text(encoding='utf-8')
source = re.sub(r'const ASSETS = \[[\s\S]*?\];',
                'const ASSETS = ' + json.dumps(['./'] + ['./' + path.relative_to(ROOT / 'pwa').as_posix()
                                                        for path in assets], indent=2) + ';', source)
worker.write_text(re.sub(r"const CACHE = 'egginc-mission-shell-[^']+';",
                         "const CACHE = 'egginc-mission-shell-" + version + "';", source), encoding='utf-8')
